import sys

def main():
    s = sys.stdin.read().strip()
    n = len(s)
    dp = [0] * n
    max_len = 0
    count = 0

    for i in range(n):
        if s[i] == ')':
            if i > 0 and s[i-1] == '(':
                if i >= 2:
                    dp[i] = dp[i-2] + 2
                else:
                    dp[i] = 2
            elif i > 0 and s[i-1] == ')':
                prev_len = dp[i-1]
                if i - prev_len - 1 >= 0 and s[i - prev_len - 1] == '(':
                    dp[i] = dp[i-1] + 2
                    if i - prev_len - 2 >= 0:
                        dp[i] += dp[i - prev_len - 2]

        if dp[i] > 0:
            if dp[i] > max_len:
                max_len = dp[i]
                count = 1
            elif dp[i] == max_len:
                count += 1

    if max_len == 0:
        print("0 1")
    else:
        print(f"{max_len} {count}")

if __name__ == "__main__":
    main()
